// LSH hotel.daily-report → a one-line digest for email / chat.
const b = $input.first().json.body || {};
const d = b.data || {};
const rev = Object.entries(d.revenue || {}).map(([c, v]) => v + ' ' + c).join(', ') || '0';
const rooms = (d.byRoom || []).map(r => r.room + ':' + r.orders).join(', ') || '—';
const summary = '📊 ' + d.date + ': ' + d.orders + ' orders, revenue ' + rev + ', pending acks ' + d.pendingAcks + '. By room: ' + rooms;
return [{ json: { event: b.event, hub: b.hub, summary, report: d } }];
